const TEMPERATURE_UNITS = {
  CELSIUS: 'c',
  FAHRENHEIT: 'f',
};

function TemperatureConverter() {
  const [temperature, setTemperature] = useState(0);
  const [unit, setUnit] = useState(TEMPERATURE_UNITS.CELSIUS);
